    /** @throws InvalidPricesFileException */
    public function parse(string $json): PriceFileSpec
    {
        $decoded = json_decode($json, true, 512, JSON_THROW_ON_ERROR); // catch → throw InvalidPricesFileException("invalid JSON: ...")
        if (!is_array($decoded)) throw ...
        // top-level keys
        foreach (['providers','models','prices'] as $key) {
            if (!array_key_exists($key, $decoded)) throw new InvalidPricesFileException("missing section '{$key}'");
            if (!is_array($decoded[$key])) throw ...
        }
        // Hmm, reprice allows omitting providers/models. So: providers/models are optional (absent => []), prices is required.
        $providers = $this->parseProviders($decoded['providers'] ?? []);
        $models = $this->parseModels($decoded['models'] ?? []);
        $rows = $this->parseRows($decoded['prices'] ?? []);
        if ($rows === []) throw new InvalidPricesFileException("section 'prices' must contain at least one price row");
        return new PriceFileSpec($providers, $models, $rows);
    }
```

