final class PricesImportService
{
    public function __construct(private readonly EntityManagerInterface $em, private readonly RateCalculator $calculator) {}

    /** @return array{providers:int, models:int, price_rows:int} */
    public function import(PriceFileSpec $spec): array
    {
        $em = $this->em;
        return $em->transactional(function (EntityManagerInterface $em) use ($spec): array {
            $providersUpserted = 0;
            $providerMap = [];
            foreach ($spec->providers as $p) {
                $existing = $em->getRepository(Provider::class)->findOneBy(['code' => $p->code]);
                if ($existing instanceof Provider) {
                    $existing->update(...);
                } else {
                    $provider = new Provider($p->code, $p->name, $p->offPeak?->startMinutes, ...);
                    $em->persist($provider);
                }
                $providerMap[$p->code] = $existing ?? $provider;
                $providersUpserted++;
            }
            // models: resolve provider for spec.providerCode from map or DB
            $modelsUpserted = 0;
            $modelMap = [];
            foreach ($spec->models as $m) {
                $provider = $providerMap[$m->providerCode] ?? $em->getRepository(Provider::class)->findOneBy(['code' => $m->providerCode])
                    ?? throw new InvalidPricesFileException("model '{$m->code}': unknown provider '{$m->providerCode}'");
                $existing = $em->getRepository(Model::class)->findOneBy(['provider' => $provider, 'code' => $m->code]);
                if ($existing) { $modelMap[...] = $existing; }
                else { $model = new Model($m->code, $provider); $em->persist($model); $modelMap[...] = $model; }
                $modelsUpserted++;
            }
            // rows: resolve provider + model (from map or DB)
            $rowsUpserted = 0;
