```php
public function import(array $specs): array{inserted:int, skipped:int}
{
    return $em->transactional(function ($em) use ($specs) {
        $inserted = 0; $skipped = 0;
        $seen = [];
        foreach ($specs as $spec) {
            $key = $spec->provider . "\x1f" . $spec->requestId;
            if (isset($seen[$key])) { $skipped++; continue; } // duplicate within the file
            $seen[$key] = true;
            $provider = $em->getRepository(Provider::class)->findOneBy(['code' => $spec->provider])
                ?? throw new InvalidUsageFileException("line {$spec->line}: unknown provider '{$spec->provider}'");
            $model = $em->getRepository(Model::class)->findOneBy(['provider' => $provider, 'code' => $spec->model])
                ?? throw new InvalidUsageFileException("line {$spec->line}: unknown model '{$spec->provider}/{$spec->model}'");
            $exists = $em->createQuery('SELECT e.id FROM UsageEvent e WHERE e.provider = :p AND e.providerRequestId = :r')
                ->setParameter('p', $provider)->setParameter('r', $spec->requestId)->getOneOrNullResult();
            if ($exists) { $skipped++; continue; }
            $event = new UsageEvent($provider, $model, $spec->requestId, $spec->user, $spec->ts, $spec->tokens);
            $em->persist($event);
            $inserted++;
        }
        $em->flush();
        return ['inserted' => $inserted, 'skipped' => $skipped];
    });
}
