The rateAll implementation:
```php
return $this->em->transactional(function (EntityManagerInterface $em): RatingResult {
    $pending = $em->createQuery(
        'SELECT e FROM UsageEvent e WHERE e.status = :st ORDER BY e.id ASC'
    )->setParameter('st', UsageStatus::Pending)->getResult();

    $rated = 0;
    $unrated = [];
    foreach ($pending as $event) {
        $row = $em->createQuery(
            'SELECT r FROM PriceRow r WHERE r.model = :model AND r.validFrom <= :ts ORDER BY r.validFrom DESC'
        )->setParameter('model', $event->getModel())->setParameter('ts', $event->getTs(), Types::DATETIME_IMMUTABLE)->setMaxResults(1)->getOneOrNullResult();

        if ($row === null) {
            $unrated[] = new UnratedEvent($event->getProvider()->getCode(), $event->getProviderRequestId(), $event->getTs());
            continue;
        }

        $cost = $this->calculator->eventCost(
            $event->getTokenCounts(),
            $row,
            $event->getProvider()->offPeakPolicy(),
            TimeOfDay::minutesOfDayUtc($event->getTs()),
        );
        $event->markRated($cost, $row, new DateTimeImmutable());
        $rated++;
    }
    $em->flush();

    return new RatingResult($rated, $unrated);
});
```

