public function build(ContainerBuilder $container): void
{
    if (!str_contains((string)getenv('APP_DEBUG_DUMP'), '1')) {
        return;
    }

    $probe = (fn (string $label) => new class($label) implements CompilerPassInterface {
        public function __construct(private string $label) {}

        public function process(ContainerBuilder $c): void
        {
            $target = 'App\\Doctrine\\UserQuotedQuoteStrategy';
            $out = "[{$this->label}] hasDef=".var_export($c->hasDefinition($target), true);
            if ($c->hasDefinition($target)) {
                $d = $c->getDefinition($target);
                $out .= ' public='.var_export($d->isPublic(), true);
            }
            if ($c->hasAlias('doctrine.orm.entity_manager')) {
                $out .= ' aliasTarget='.(string)$c->getAlias('doctrine.orm.entity_manager').' aliasPublic='.var_export($c->getAlias('doctrine.orm.entity_manager')->isPublic(), true);
            } else {
                $out .= ' noAlias';
            }
            if ($c->hasDefinition('doctrine.orm.default_configuration')) {
                $cd = $c->getDefinition('doctrine.orm.default_configuration');
                $refs = [];
                foreach ($cd->getMethodCalls() as $mc) {
                    foreach ($mc[1] as $a) {
                        if ($a instanceof \\Symfony\\Component\\DependencyInjection\\Reference) {
                            $refs[] = (string)$a;
                        }
                    }
                }
                $out .= ' configMethodRefs=['.implode(',', array_unique(array_filter($refs, fn($r) => str_contains($r, 'Quote')))).']';
                foreach ($cd->getArguments() as $a) {
                    if ($a instanceof \\Symfony\\Component\\DependencyInjection\\Reference) {
                        $out .= ' argRef='.(string)$a;
                    }
                }
            }
            fwrite(STDERR, $out."\n");
        }
    })(__FUNCTION__)) ?? null;

    $mk = static function (string $label): CompilerPassInterface {
        return new class($label) implements CompilerPassInterface {
            public function __construct(private string $label) {}

            public function process(ContainerBuilder $c): void
            {
                $target = 'App\\Doctrine\\UserQuotedQuoteStrategy';
                $out = "[{$this->label}] hasDef=".var_export($c->hasDefinition($target), true);
                if ($c->hasDefinition($target)) {
                    $out .= ' public='.var_export($c->getDefinition($target)->isPublic(), true);    }
                if ($c->hasAlias('doctrine.orm.entity_manager')) {
                    $out .= ' aliasTarget='.(string)$c->getAlias('doctrine.orm.entity_manager').' aliasPublic='.var_export($c->getAlias('doctrine.orm.entity_manager')->isPublic(), true) ;
                } else {
                    $out .= ' noAlias';
                }
                if ($c->hasDefinition('doctrine.orm.default_configuration')) {
                    $cd = $c->getDefinition('doctrine.orm.default_configuration');
                    $refs = [];
                    foreach ($cd->getMethodCalls() as $mc) {
                        foreach ($mc[1] as $a) {
                            if ($a instanceof \\Symfony\\Component\\DependencyInjection\\Reference) {
                                $refs[] = (string)$a;
                            }
                        }
                    }
                    $out .= ' quoteRefs=['.implode(',', array_unique(array_filter($refs, fn($r) => str_contains($r, 'Quote')))).']';
                }
                fwrite(STDERR, $out."\n");
            }
        };
    };

    $container->addCompilerPass($mk('afterOptimization'), PassConfig::TYPE_BEFORE_REMOVING, 0);
    $container->addCompilerPass($mk('beforeRemove'), PassConfig::TYPE_REMOVE, -1000);
    $container->addCompilerPass($mk('afterRemove'), PassConfig::TYPE_REMOVE, 1000);
}

